    "nav.sites": "Your sites", "nav.activity": "Activity", "nav.settings": "Settings", "nav.agent": "AI agent", "site.convert": "Convert to a Histeon project", "site.convertHint": "The pages of the latest version become a Histeon CMS project to edit in the builder; you see the check and the preview first.", "site.convertNeedsBuild": "The site needs a ready version: the conversion starts from its files.", "app.breadcrumb": "Where you are", "app.skipToContent": "Skip to content", "app.routeMissing": "This address no longer leads anywhere: you are back to your sites.", "new.prototypeNotice": "This is a Histeon prototype: import it as an editable project, with pages, templates and content, instead of publishing it as it is.", "new.prototypeImport": "Import into Histeon CMS", "home.emptyPrototype": "Have a Histeon prototype?", "home.emptyPrototypeAction": "Import it →", "site.cmsEyebrow": "DESTINATION · HISTOS CMS", "site.deployFtpNote": "The files are really uploaded to the server. Files that are not in the new version stay where they are.", "site.cmsSubtitle": "Publishes the project «{project}»", "site.cmsOpenProject": "Open the project", "site.cmsCardTitle": "«{project}» lands here", "site.cmsCardBody": "This site has no files of its own: it receives the versions of the Histeon CMS project. Choose Cloudflare or the hosting below and verify the connection; then create the version and publish from the project, after the summary.", "agent.eyebrow": "AI AGENT", "agent.title": "AI agent", "agent.subtitle": "Connect Claude Code, Codex, Claude Desktop or ChatGPT desktop: the agent imports your prototypes, runs builds and previews, and asks you before it touches WordPress.", "agent.settingsBody": "The connector for AI agents has its own screen: guided connection, agent activity and WordPress permissions.", "agent.settingsOpen": "Open AI agent →", "agent.catalogLink": "Or let your AI agent import it →", "nav.local": "Everything stays on your computer",
