    "delete.select": "Select", "delete.selection": "Selection", "delete.pickLabel": "Select “{name}”", "delete.pickedCount": "{count} selected", "delete.pickAll": "Select all", "delete.pickNone": "Select none", "delete.deletePicked": "Move to the Bin ({count})", "delete.menuOpen": "Open", "delete.menuPick": "Select", "delete.menuUnpick": "Deselect", "delete.menuDelete": "Move to the Bin…", "delete.titleProjectOne": "Move the CMS project to the Bin?", "delete.titleProjects": "Move {count} CMS projects to the Bin?", "delete.titleSiteOne": "Move the site to the Bin?", "delete.titleSites": "Move {count} sites to the Bin?", "delete.bodyProjects": "The project leaves the catalog for the Bin, with its pages, posts, content and media; its builds are removed at once (they are made again when needed). From the Bin it comes back as it was for {days} days, then it is gone for good. A site already published stays online and WordPress is not touched. To confirm, copy the name of each project and paste it in the field below.", "delete.bodySites": "The site leaves the list for the Bin, with its builds, history and the credentials saved in the keyring. From the Bin it comes back as it was for {days} days, then it is gone for good, credentials included. The published site stays online. To confirm, copy the name of each site and paste it in the field below.", "nav.trash": "Bin", "trash.eyebrow": "RECENTLY DELETED", "trash.title": "Bin", "trash.subtitle": "Deleted CMS projects and sites. They come back as they were for {days} days; then Histeon Publish deletes them for good.", "trash.projects": "CMS projects", "trash.sites": "Sites", "trash.empty": "The Bin is empty.", "trash.loading": "Reading the Bin…", "trash.deletedAt": "Deleted on {date}", "trash.expires": "goes by itself on {date}", "trash.restore": "Restore", "trash.purge": "Delete for good…", "trash.emptyAll": "Empty the Bin…", "trash.restored": "“{name}” restored.", "purge.titleOne": "Delete “{name}” for good?", "purge.titles"