/** Whether a message exists for the key, in the language or in Italian. */
export function hasMessage(language: Language, key: string): boolean {
  return key in messages[language] || key in messages.it;
}

const pluralRules = new Map<Language, Intl.PluralRules>();

/**
 * `{key}.one` or `{key}.other`, chosen by the language's plural rules, with `{n}` set to the count: "1 articolo",
 * "2 articoli". Other CLDR categories (Italian "many" for a million) fall back to `.other`.
 */
export function plural(language: Language, key: string, n: number, values: Record<string, string | number> = {}): string {
  let rules = pluralRules.get(language);
  if (!rules) {
    rules = new Intl.PluralRules(language === "it" ? "it-IT" : "en-US");
    pluralRules.set(language, rules);
  }
  const exact = `${key}.${rules.select(n)}`;
  return translate(language, hasMessage(language, exact) ? exact : `${key}.other`, { n, ...values });
}

export type StateTone = "ready" | "blocked" | "stale" | "failed" | "running" | "neutral";

const STATE_TONES: Record<string, StateTone> = {
  ready: "ready", complete: "ready", deployed: "ready", published: "ready", added: "ready",
  blocked: "blocked", failed: "failed", interrupted: "failed", unavailable: "failed",
  stale: "stale", cancelled: "neutral", running: "running", waiting: "neutral", new: "neutral", draft: "neutral", archived: "neutral",
};

/**
 * One name and one tone for every state the app shows (E13), the same in chips, History, Activity and home: a build,
 * a publish, a job, a page or a record. An unknown state keeps its raw value, in a neutral chip.
 */
export function stateLabel(language: Language, status: string): { label: string; tone: StateTone } {
  const key = `state.${status}`;
  return hasMessage(language, key) ? { label: translate(language, key), tone: STATE_TONES[status] ?? "neutral" } : { label: status, tone: "neutral" };
}

export function translate(language: Language, key: string, values: Record<string, string | number> = {}): string {
  let message = messages[language][key] ?? messages.it[key] ?? key;
  // A function, so "$&" or "$$" in a value (a file path, a project name) stay as they are.
  for (const [name, value] of Object.entries(values)) message = message.replaceAll(`{${name}}`, () => String(value));
  return message;
}
